package com.bank.refdata;

import java.util.*;
import java.util.logging.*;

public class RefDataDemo {
    private static final Logger log = Logger.getLogger("RefData");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> employees = List.of(
            new Employee(1L, "Rajesh"), new Employee(2L, "Priya"), new Employee(3L, "Amit"));
        ReferenceDataService service = new ReferenceDataService();

        List<String> names = service.immutableNames(employees);
        Map<Long, String> lookup = service.immutableLookup(employees);
        log.info(() -> "Names: " + names);
        log.info(() -> "Lookup id=2: " + lookup.get(2L));
        try {
            names.add("Hacker");
        } catch (UnsupportedOperationException ex) {
            log.warning("Immutable list rejected modification as expected");
        }
    }
}

// ─── Would be in model/Employee.java ───
record Employee(Long id, String name) {}

// ─── Would be in service/ReferenceDataService.java ───
class ReferenceDataService {
    // collect to list, THEN wrap unmodifiable as the finishing step
    List<String> immutableNames(List<Employee> employees) {
        return employees.stream()
            .map(Employee::name)
            .collect(java.util.stream.Collectors.collectingAndThen(
                java.util.stream.Collectors.toList(),
                java.util.Collections::unmodifiableList));
    }

    // collect to map, THEN seal it
    Map<Long, String> immutableLookup(List<Employee> employees) {
        return employees.stream()
            .collect(java.util.stream.Collectors.collectingAndThen(
                java.util.stream.Collectors.toMap(Employee::id, Employee::name),
                java.util.Collections::unmodifiableMap));
    }
}
